325	        currentOwner.setLastName(ownerFieldsDto.getLastName());
326	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
327	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
328	        this.clinicService.saveOwner(currentOwner);
329	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
