410	    /**
411	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
412	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
413	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
414	     *
415	     * @param ownerFieldsDto the submitted owner fields
416	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
417	     *                                     name of every offending field
418	     */
419	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
420	        List<String> missingFields = new ArrayList<>();
421	        if (isBlank(ownerFieldsDto.getFirstName())) {
422	            missingFields.add("firstName");
423	        }
424	        if (isBlank(ownerFieldsDto.getLastName())) {
425	            missingFields.add("lastName");
426	        }
427	        if (!hasAddress(ownerFieldsDto)) {
428	            missingFields.add("address");
429	        }
430	        if (isBlank(ownerFieldsDto.getCity())) {
431	            missingFields.add("city");
432	        }
433	        if (isBlank(ownerFieldsDto.getTelephone())) {
434	            missingFields.add("telephone");
435	        }
436	        if (!missingFields.isEmpty()) {
437	            throw new InvalidOwnerFieldsException(missingFields);
438	        }
439	    }
440	
441	    private boolean isBlank(String value) {
442	        return value == null || value.isBlank();
443	    }
444	
445	    /**
446	     * Reports whether an existing owner has not been soft-deleted. The create endpoint's duplicate
447	     * and identity checks consider only live owners, so an owner flagged {@code deleted} no longer
448	     * blocks a new owner that would otherwise match it.
449	     *
450	     * @param owner an existing owner
451	     * @return {@code true} unless the owner is flagged deleted
452	     */
453	    private boolean isNotDeleted(Owner owner) {
454	        return !Boolean.TRUE.equals(owner.getDeleted());
455	    }
456	
457	    /**
458	     * Rejects a supplied {@code registrationDate} that is later than the current server date. A
459	     * {@code null} value means the field was omitted and the registration date will default to the
460	     * server date, so there is nothing to reject. A supplied date on or before today is accepted; the
461	     * raw supplied value is compared against the server date before any business-day adjustment.
462	     *
463	     * @param registrationDate the registration date supplied by the client, or {@code null} if omitted
464	     * @throws InvalidOwnerFieldsException if the supplied date is later than the server date, yielding a
465	     *                                     400 Bad Request response
466	     */
467	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
468	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
469	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
470	        }
471	    }
472	
473	    /**
474	     * Validates an owner's optional postcode. A {@code null} value means the field was omitted and is
475	     * left unset, keeping the create contract backward-compatible. When a value is present it must be
476	     * exactly 4 digits, and when the owner's region (derived from its city, {@link #regionForCity})
477	     * has a known postcode range in {@link #REGION_POSTCODES} the postcode must fall within that
478	     * inclusive range. A region with no known range ({@code 'UNKNOWN'}) accepts any 4-digit postcode.
479	     * The returned value is stored and returned unchanged.
480	     *
481	     * @param postcode the raw postcode value submitted by the client, or {@code null} if omitted
482	     * @param region   the owner's region derived from its city
483	     * @return the postcode to store, or {@code null} if none was supplied
484	     * @throws InvalidOwnerFieldsException if a value is present but not a valid 4-digit postcode, or is
485	     *                                     out of range for the city's region, yielding a 400 response
486	     */
487	    private String validatePostcode(String postcode, String region) {
488	        if (postcode == null) {
489	            return null;
490	        }
491	        if (!postcode.matches("[0-9]{4}")) {
492	            throw new InvalidOwnerFieldsException(List.of("postcode"));
493	        }
494	        int[] range = REGION_POSTCODES.get(region);
495	        if (range != null) {
496	            int value = Integer.parseInt(postcode);
497	            if (value < range[0] || value > range[1]) {
498	                throw new InvalidOwnerFieldsException(List.of("postcode"));
499	            }
500	        }
501	        return postcode;
502	    }
503	
504	    /**
505	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
506	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
507	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
508	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
509	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
510	     *
511	     * @param telephone the raw telephone value submitted by the client
512	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
513	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
514	     *                                     400 response
515	     */
516	    private String normalizeTelephone(String telephone) {
517	        String e164 = toE164(telephone);
518	        if (e164 == null) {
519	            throw new InvalidOwnerFieldsException(List.of("telephone"));
520	        }
521	        return e164;
522	    }
523	
524	    /**
525	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
526	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
527	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
528	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits,
529	     * and when the supplied country code is one with a known national-number length
530	     * ({@link #NATIONAL_NUMBER_LENGTHS}, e.g. {@code '+61'} => 9, {@code '+1'} => 10) the national
531	     * number must have exactly that many digits.
532	     *
533	     * @param telephone the raw telephone value, possibly {@code null}
534	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
535	     */
536	    private String toE164(String telephone) {
537	        if (telephone == null) {
538	            return null;
539	        }
540	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
541	        boolean hasPlus = cleaned.startsWith("+");
542	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
543	        String nationalSignificant = hasPlus
544	            ? digits
545	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
546	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
547	            return null;
548	        }
549	        if (!hasValidNationalNumberLength(nationalSignificant)) {
550	            return null;
551	        }
552	        return "+" + nationalSignificant;
553	    }
554	
555	    /**
556	     * Checks the national-number length of an E.164 number (country code plus national significant
557	     * digits, no leading {@code '+'}) against the per-country requirement in
558	     * {@link #NATIONAL_NUMBER_LENGTHS}. The longest listed country code that prefixes the number
559	     * selects the requirement, and the remaining digits must number exactly that many. A number whose
560	     * country code is not listed carries no per-country length requirement and is accepted.
561	     *
562	     * @param nationalSignificant the digits of the E.164 number, country code first, without the
563	     *                            leading {@code '+'}
564	     * @return {@code true} if the national-number length is correct for the country code, or the
565	     *         country code has no listed requirement; {@code false} otherwise
566	     */
567	    private boolean hasValidNationalNumberLength(String nationalSignificant) {
568	        String countryCode = NATIONAL_NUMBER_LENGTHS.keySet().stream()
569	            .filter(nationalSignificant::startsWith)
570	            .max(Comparator.comparingInt(String::length))
571	            .orElse(null);
572	        if (countryCode == null) {
573	            return true;
574	        }
575	        int nationalLength = nationalSignificant.length() - countryCode.length();
576	        return nationalLength == NATIONAL_NUMBER_LENGTHS.get(countryCode);
577	    }
578	
579	    /**
580	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
581	     * is left unset. When a value is present it must be a syntactically valid address whose domain is
582	     * not on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); the stored and
583	     * returned value is that address lower-cased.
584	     *
585	     * @param email the raw email value submitted by the client, or {@code null} if omitted
586	     * @return the lower-cased email, or {@code null} if none was supplied
587	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
588	     *                                     or its domain is a disposable-mail domain, yielding a 400
589	     *                                     response
590	     */
591	    private String normalizeEmail(String email) {
592	        if (email == null) {
593	            return null;
594	        }
595	        if (!EMAIL_PATTERN.matcher(email).matches()) {
596	            throw new InvalidOwnerFieldsException(List.of("email"));
597	        }
598	        String normalized = email.toLowerCase(Locale.ROOT);
599	        String domain = normalized.substring(normalized.indexOf('@') + 1);
600	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
601	            throw new InvalidOwnerFieldsException(List.of("email"));
602	        }
603	        return normalized;
604	    }
605	
606	    /**
607	     * Counts the existing owners that, before this create, already share the given first name and
608	     * last name. Both names are compared case-insensitively with surrounding and internal whitespace
609	     * collapsed, consistent with the other owner-name comparisons. The owner being created has not
610	     * been saved yet, so it is never included in the count.
611	     *
612	     * @param firstName the first name of the owner being created
613	     * @param lastName  the last name of the owner being created
614	     * @return the number of existing owners sharing both names
615	     */
616	    private int countNamesakes(String firstName, String lastName) {
617	        String normalizedFirstName = normalizeForComparison(firstName);
618	        String normalizedLastName = normalizeForComparison(lastName);
619	        return (int) this.clinicService.findAllOwners().stream()
620	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
621	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
622	            .count();
623	    }
624	
625	    /**
626	     * Builds the owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is
627	     * the region code derived from the owner's postcode ({@link #regionForPostcode}, {@code 'UNKNOWN'}
628	     * when the postcode is absent or in no known range), and {@code HASH8} is the first eight
629	     * upper-cased hex characters of the SHA-256 digest of the owner's normalized telephone followed by
630	     * the last name (e.g. {@code 'NSW-1A2B3C4D'}). The identity carries no sequence number, so the
631	     * same postcode region, telephone and last name always yield the same customer code.
632	     *
633	     * <p>If the computed code collides with an existing owner's {@code customerCode}, it is
634	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes
635	     * it unique, so distinct owners always receive distinct customer codes.
636	     *
637	     * @param postcode  the owner's validated postcode, or {@code null} if none was supplied
638	     * @param telephone the owner's normalized (E.164) telephone
639	     * @param lastName  the owner's last name
640	     * @return the formatted, de-duplicated customer code
641	     */
642	    private String generateCustomerCode(String postcode, String telephone, String lastName) {
643	        String region = regionForPostcode(postcode);
644	        String hash8 = hashHex(telephone + lastName, 8);
645	        String baseCode = region + "-" + hash8;
646	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
647	            .map(Owner::getCustomerCode)
648	            .filter(Objects::nonNull)
649	            .collect(Collectors.toSet());
650	        if (!existingCodes.contains(baseCode)) {
651	            return baseCode;
652	        }
653	        int n = 2;
654	        while (existingCodes.contains(baseCode + "-" + n)) {
655	            n++;
656	        }
657	        return baseCode + "-" + n;
658	    }
659	
660	    /**
661	     * Resolves the region code for a postcode by its known 4-digit range in {@link #REGION_POSTCODES}
662	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), returning {@code 'UNKNOWN'}
663	     * when the postcode is {@code null}, not exactly 4 digits, or falls in no known range. This is the
664	     * {@code <REGION>} segment baked into the {@code customerCode}.
665	     *
666	     * @param postcode the owner's postcode, or {@code null}
667	     * @return the region code, or {@code 'UNKNOWN'}
668	     */
669	    private String regionForPostcode(String postcode) {
670	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
671	            return "UNKNOWN";
672	        }
673	        int value = Integer.parseInt(postcode);
674	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
675	            int[] range = entry.getValue();
676	            if (value >= range[0] && value <= range[1]) {
677	                return entry.getKey();
678	            }
679	        }
680	        return "UNKNOWN";
681	    }
682	
683	    /**
684	     * Resolves the region code for a city via the fixed {@link #CITY_REGION} table
685	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), returning {@code 'UNKNOWN'}
686	     * when the city is not listed. Used to validate an owner's optional postcode against its city's
687	     * region.
688	     *
689	     * @param city the owner's city
690	     * @return the region code, or {@code 'UNKNOWN'}
691	     */
692	    private String regionForCity(String city) {
693	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
694	    }
695	
696	    /**
697	     * Returns the first {@code length} upper-cased hex characters of the SHA-256 digest of the given
698	     * input. Used for the {@code <HASH8>} segment of a {@code customerCode} (length 8) and for the
699	     * deterministic {@code householdId} (length 12).
700	     *
701	     * @param input  the value to hash
702	     * @param length the number of leading hex characters to return
703	     * @return the first {@code length} upper-cased hex characters of its SHA-256 digest
704	     */
705	    private String hashHex(String input, int length) {
706	        try {
707	            byte[] digest = MessageDigest.getInstance("SHA-256")
708	                .digest(input.getBytes(StandardCharsets.UTF_8));
709	            StringBuilder hex = new StringBuilder(digest.length * 2);
710	            for (byte b : digest) {
711	                hex.append(String.format("%02x", b));
712	            }
713	            return hex.substring(0, length).toUpperCase(Locale.ROOT);
714	        } catch (NoSuchAlgorithmException e) {
715	            throw new IllegalStateException("SHA-256 algorithm not available", e);
716	        }
717	    }
718	
719	    /**
720	     * Counts the existing owners already in the given city, used to derive the per-city sequence of a
721	     * {@code customerCode}. Cities are compared case-insensitively with surrounding and internal
722	     * whitespace collapsed, consistent with the other owner-field comparisons. The owner being created
723	     * has not been saved yet, so it is never included in the count.
724	     *
725	     * @param city the city of the owner being created
726	     * @return the number of existing owners in that city
727	     */
728	    private int countOwnersInCity(String city) {
729	        String normalizedCity = normalizeForComparison(city);
730	        return (int) this.clinicService.findAllOwners().stream()
731	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
732	            .count();
733	    }
734	
735	    /**
736	     * Rejects creation of an owner whose city already contains the maximum number of owners
737	     * ({@value #CITY_CAPACITY}). Owners are counted per city case-insensitively with surrounding and
738	     * internal whitespace collapsed, consistent with the other owner-field comparisons.
739	     *
740	     * @param city the city of the owner being created
741	     * @throws OwnerCityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more
742	     *                                      owners, yielding a 409 Conflict response
743	     */
744	    private void rejectCityAtCapacity(String city) {
745	        if (countOwnersInCity(city) >= CITY_CAPACITY) {
746	            throw new OwnerCityAtCapacityException(city);
747	        }
748	    }
749	
750	    /**
751	     * Rejects creation of an owner once the given business day has already reached its daily quota
752	     * of {@value #DAILY_OWNER_LIMIT} owners. Owners are counted by their {@code registrationDate}
753	     * being that day — the adjusted business day the owner being created will carry — so the quota
754	     * applies per business day. The owner being created has not been saved yet, so it is never
755	     * included in the count.
756	     *
757	     * @param registrationDate the adjusted business-day registration date of the owner being created
758	     * @throws DailyOwnerLimitReachedException if {@value #DAILY_OWNER_LIMIT} or more owners already
759	     *                                         carry that registration date, yielding a
760	     *                                         429 Too Many Requests response
761	     */
762	    private void rejectDailyLimitReached(LocalDate registrationDate) {
763	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
764	            throw new DailyOwnerLimitReachedException(registrationDate);
765	        }
766	    }
767	
768	    /**
769	     * Counts the existing owners that carry the given day as their {@code registrationDate} — the same
770	     * per-business-day bucket the daily create-limit and the bulk-signup warning both accumulate over.
771	     *
772	     * @param registrationDate the business day to count owners for
773	     * @return the number of existing owners registered on that day
774	     */
775	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
776	        return this.clinicService.findAllOwners().stream()
777	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
778	            .count();
779	    }
780	
781	    /**
782	     * Sets the {@code bulkSignupWarning} flag on an owner response. The flag is {@code true} when more
783	     * than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the current business day's
784	     * {@code registrationDate} — the business day a create would land on right now — and {@code false}
785	     * otherwise.
786	     *
787	     * @param ownerDto the owner response to flag
788	     */
789	    private void applyBulkSignupWarning(OwnerDto ownerDto) {
790	        LocalDate today = toBusinessDay(LocalDate.now());
791	        ownerDto.setBulkSignupWarning(countOwnersRegisteredOn(today) > BULK_SIGNUP_WARNING_THRESHOLD);
792	    }
793	
794	    /**
795	     * Rolls a registration date forward to a business day. A date that falls on a Saturday, a Sunday
796	     * or a listed {@linkplain #PUBLIC_HOLIDAYS public holiday} is rolled forward one day at a time
797	     * until it reaches the next non-holiday weekday; a date already on a non-holiday weekday is
798	     * returned unchanged. This applies to the effective registration date whether it was supplied in
799	     * the request or defaulted to the server date, and the adjusted value is what gets stored as
800	     * {@code registrationDate} and feeds every value derived from it (such as the membership number's
801	     * year segment and the daily create-limit's per-day bucket).
802	     *
803	     * @param date the effective registration date, supplied or defaulted
804	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
805	     */
806	    private LocalDate toBusinessDay(LocalDate date) {
807	        LocalDate adjusted = date;
808	        while (adjusted.getDayOfWeek() == DayOfWeek.SATURDAY
809	            || adjusted.getDayOfWeek() == DayOfWeek.SUNDAY
810	            || PUBLIC_HOLIDAYS.contains(adjusted)) {
811	            adjusted = adjusted.plusDays(1);
812	        }
813	        return adjusted;
814	    }
815	
816	    /**
817	     * Rejects creation of an owner whose derived {@code identityKey} exactly matches an existing
818	     * owner's. The identity key — {@code '<normalizedTelephone>|<email or empty>|<householdId or
819	     * empty>'} — is the single value that consolidates all duplicate detection: the previously
820	     * separate telephone, email and household checks are all expressed through it. Because the
821	     * telephone is part of the key, two members of the same household (same {@code householdId})
822	     * with different telephones have different identity keys and are both allowed; only a whole-key
823	     * match is a duplicate. The owner being created already carries its normalized telephone,
824	     * email and (if any) household id, and existing owners store the same normalized forms, so the
825	     * keys are compared directly.
826	     *
827	     * @param owner the owner being created, with its telephone, email and household id already set
828	     * @throws DuplicateOwnerIdentityException if another owner already has the same identity key,
829	     *                                         yielding a 409 Conflict response
830	     */
831	    private void rejectDuplicateIdentity(Owner owner) {
832	        String identityKey = owner.getIdentityKey();
833	        boolean inUse = this.clinicService.findAllOwners().stream()
834	            .filter(this::isNotDeleted)
835	            .map(Owner::getIdentityKey)
836	            .anyMatch(identityKey::equals);
837	        if (inUse) {
838	            throw new DuplicateOwnerIdentityException(identityKey);
839	        }
840	    }
841	
842	    /**
843	     * Flags the owner being created as a possible (soft) duplicate. A possible duplicate is an owner
844	     * that is not a hard duplicate (its identity key is unique, so it has already passed
845	     * {@link #rejectDuplicateIdentity}) yet belongs to the same household as an existing owner — that
846	     * is, it carries the same computed {@code householdId} (derived from the last name and postcode) —
847	     * while carrying a different telephone. When such a match exists the owner is created with
848	     * {@code possibleDuplicate} set to {@code true} and {@code possibleDuplicateOf} set to the matching
849	     * owner's id (the earliest matching owner by id); otherwise {@code possibleDuplicate} is
850	     * {@code false} and {@code possibleDuplicateOf} is left unset.
851	     *
852	     * <p>An owner that declares household membership via {@code sharesHousehold} is never flagged: a
853	     * declared household member is not a suspected duplicate. (Without that declaration a same-household
854	     * owner is rejected outright by {@link #rejectHouseholdDuplicate}, so no suspected-duplicate match
855	     * survives for a created owner either.)
856	     *
857	     * @param owner           the owner being created, with its household id and telephone already set
858	     * @param sharesHousehold whether the owner declared itself a member of an existing household
859	     */
860	    private void applyPossibleDuplicate(Owner owner, boolean sharesHousehold) {
861	        owner.setPossibleDuplicate(false);
862	        if (sharesHousehold) {
863	            return;
864	        }
865	        String householdId = owner.getHouseholdId();
866	        if (householdId == null || householdId.isBlank()) {
867	            return;
868	        }
869	        String telephone = owner.getTelephone();
870	        Owner match = this.clinicService.findAllOwners().stream()
871	            .filter(this::isNotDeleted)
872	            .filter(existing -> householdId.equals(existing.getHouseholdId())
873	                && !Objects.equals(telephone, existing.getTelephone()))
874	            .min(Comparator.comparingInt(Owner::getId))
875	            .orElse(null);
876	        if (match != null) {
877	            owner.setPossibleDuplicate(true);
878	            owner.setPossibleDuplicateOf(match.getId());
879	        }
880	    }
881	
882	    /**
883	     * Computes the owner's deterministic {@code householdId}: the first twelve upper-cased hex
884	     * characters of the SHA-256 digest of the normalized last name and the postcode joined by a
885	     * {@code '|'}. Because the value derives only from the last name and postcode, every owner that
886	     * shares both automatically shares the same household id, so the household is keyed on
887	     * {@code (lastName, postcode)} with no opt-in required. The last name is normalized for comparison
888	     * (trimmed, internal whitespace collapsed, lower-cased) so values differing only in case or spacing
889	     * still land in the same household.
890	     *
891	     * @param lastName the owner's last name
892	     * @param postcode the owner's validated postcode, or {@code null} if none was supplied
893	     * @return the derived household id, or {@code null} when the owner has no postcode and so belongs
894	     *         to no postcode-keyed household
895	     */
896	    private String computeHouseholdId(String lastName, String postcode) {
897	        if (postcode == null) {
898	            return null;
899	        }
900	        return hashHex(normalizeForComparison(lastName) + "|" + postcode, 12);
901	    }
902	
903	    /**
904	     * Rejects creation of an owner that would join an existing household it has not declared membership
905	     * of. The household is keyed on the computed {@code householdId} (derived from the last name and
906	     * postcode), so any existing owner carrying the same {@code householdId} is a member of the same
907	     * household. A second owner in that household is a household duplicate and is rejected with a
908	     * {@code 409 Conflict} unless the request opts in via {@code sharesHousehold}, in which case this
909	     * check is bypassed and the owner is created as a declared household member. An owner with no
910	     * {@code householdId} (no postcode) belongs to no household and is never rejected here.
911	     *
912	     * @param owner the owner being created, with its household id already computed
913	     * @throws DuplicateHouseholdException if an existing owner already belongs to the same
914	     *                                     household, yielding a 409 Conflict response
915	     */
916	    private void rejectHouseholdDuplicate(Owner owner) {
917	        String householdId = owner.getHouseholdId();
918	        if (householdId == null || householdId.isBlank()) {
919	            return;
920	        }
921	        boolean inUse = this.clinicService.findAllOwners().stream()
922	            .filter(this::isNotDeleted)
923	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
924	        if (inUse) {
925	            throw new DuplicateHouseholdException(householdId);
926	        }
927	    }
928	
929	    /**
930	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
931	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
932	     * the result is lower-cased.
933	     *
934	     * @param value the value to normalize, possibly {@code null}
935	     * @return the normalized value, or an empty string if {@code value} is {@code null}
936	     */
937	    private String normalizeForComparison(String value) {
938	        if (value == null) {
939	            return "";
940	        }
941	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
942	    }
943	
944	    /**
945	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
946	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
947	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
948	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
949	     * This normalized value is what gets stored and returned.
950	     *
951	     * @param address the raw address value submitted by the client, possibly {@code null}
952	     * @return the normalized address, or an empty string if {@code address} is {@code null}
953	     */
954	    private String normalizeAddress(String address) {
955	        if (address == null) {
956	            return "";
957	        }
958	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
959	        if (collapsed.isEmpty()) {
960	            return collapsed;
961	        }
962	        String[] tokens = collapsed.split(" ");
963	        StringBuilder normalized = new StringBuilder(collapsed.length());
964	        for (int i = 0; i < tokens.length; i++) {
965	            if (i > 0) {
966	                normalized.append(' ');
967	            }
968	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
969	        }
970	        return normalized.toString();
971	    }
972	
973	    /**
974	     * Reports whether the submitted owner supplies an address in either accepted form: a non-blank
975	     * structured {@code addressLine1}, or a non-blank flat {@code address}. The structured form is
976	     * preferred when present, but either satisfies the address requirement, keeping the create
977	     * contract backward-compatible with earlier flat-address-only owners.
978	     *
979	     * @param ownerFieldsDto the submitted owner fields
980	     * @return {@code true} if an address is supplied in either form
981	     */
982	    private boolean hasAddress(OwnerFieldsDto ownerFieldsDto) {
983	        return !isBlank(ownerFieldsDto.getAddressLine1())
984	            || !isBlank(normalizeAddress(ownerFieldsDto.getAddress()));
985	    }
986	
987	    /**
988	     * Applies the owner's address, preferring the structured form over the flat one. When a non-blank
989	     * {@code addressLine1} is supplied, it and the optional {@code addressLine2} are normalized
990	     * ({@link #normalizeAddress}) and stored, and the owner's composed {@code address} is set to the
991	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
992	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized
993	     * and stored and the structured lines are left unset. This keeps earlier flat-address owners
994	     * working while letting everything that reads the address use the composed, normalized value.
995	     *
996	     * @param owner          the owner being created
997	     * @param ownerFieldsDto the submitted owner fields
998	     */
999	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
1000	        if (!isBlank(ownerFieldsDto.getAddressLine1())) {
1001	            String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
1002	            String line2 = isBlank(ownerFieldsDto.getAddressLine2())
1003	                ? null
1004	                : normalizeAddress(ownerFieldsDto.getAddressLine2());
1005	            owner.setAddressLine1(line1);
1006	            owner.setAddressLine2(line2);
1007	            owner.setAddress(line2 != null ? line1 + " " + line2 : line1);
1008	        } else {
1009	            owner.setAddressLine1(null);
1010	            owner.setAddressLine2(null);
1011	            owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
1012	        }
1013	    }
1014	}
